class TestExtractBrokenTestNames:
    def test_line_format(self):
        errors = ["test_foo (line 10): no assert statement"]
        assert _extract_broken_test_names(errors) == {"test_foo"}

    def test_colon_format(self):
        errors = ["test_bar: runtime failure under pytest"]
        assert _extract_broken_test_names(errors) == {"test_bar"}

    def test_non_test_skipped(self):
        errors = ["module: pytest execution failed"]
        assert _extract_broken_test_names(errors) == set()

    def test_mixed(self):
        errors = [
            "test_a (line 5): empty body",
            "test_b: crash",
            "module: error",
        ]
        assert _extract_broken_test_names(errors) == {"test_a", "test_b"}

    def test_empty(self):
        assert _extract_broken_test_names([]) == set()


class TestStripBrokenFunctions:
    def test_removes_named_function(self):
        content = (
            "import os\n\ndef test_good():\n    assert True\n\ndef test_bad():\n    assert False\n"
        )
        result = _strip_broken_functions(content, {"test_bad"})
        assert "test_good" in result
        assert "test_bad" not in result

    def test_preserves_all_when_no_matches(self):
        content = "def test_a():\n    pass\n"
        result = _strip_broken_functions(content, {"test_nonexistent"})
        assert "test_a" in result

    def test_handles_syntax_error(self):
        content = "def test_a(:\n"
        result = _strip_broken_functions(content, {"test_a"})
        assert result == content

    def test_collapses_blank_lines(self):
        content = "import os\n\n\n\ndef test_keep():\n    pass\n"
        result = _strip_broken_functions(content, set())
        assert "\n\n\n" not in result
